package com.fasterxml.jackson.databind.ser.impl;

import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.databind.SerializerProvider;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

public class WritableObjectId_generateId_TriageGen0Test {

    private ObjectIdGenerator<?> mockGenerator;
    private WritableObjectId writableObjectId;

    @Before
    public void setUp() {
        mockGenerator = Mockito.mock(ObjectIdGenerator.class);
        writableObjectId = new WritableObjectId(mockGenerator);
    }

    @Test
    public void testGenerateId_ReturnsNewIdFromGenerator() {
        // Arrange
        Object inputPojo = new Object();
        String expectedId = "generated-123";
        when(mockGenerator.generateId(inputPojo)).thenReturn(expectedId);

        // Act
        Object actualId = writableObjectId.generateId(inputPojo);

        // Assert
        assertEquals("The returned ID should match the one provided by the generator", expectedId, actualId);
        assertEquals("The internal state 'id' should be updated to the new ID", expectedId, writableObjectId.getId());
    }

    @Test
    public void testGenerateId_ReturnsNullWhenGeneratorReturnsNull() {
        // Arrange
        Object inputPojo = new Object();
        when(mockGenerator.generateId(inputPojo)).thenReturn(null);

        // Act
        Object actualId = writableObjectId.generateId(inputPojo);

        // Assert
        assertNull("The returned ID should be null if the generator returns null", actualId);
        assertNull("The internal state 'id' should be null", writableObjectId.getId());
    }

    @Test
    public void testGenerateId_OverwritesExistingId() {
        // Arrange
        Object inputPojo = new Object();
        String firstId = "first-id";
        String secondId = "second-id";

        // Manually set the initial ID via generator simulation or by invoking generateId once
        when(mockGenerator.generateId(inputPojo)).thenReturn(firstId).thenReturn(secondId);

        // Act
        writableObjectId.generateId(inputPojo); // First call sets id = firstId
        Object result = writableObjectId.generateId(inputPojo); // Second call sets id = secondId

        // Assert
        assertEquals("The second call should overwrite the first ID", secondId, result);
        assertEquals("The internal state should reflect the most recent ID", secondId, writableObjectId.getId());
    }

    @Test
    public void testGenerateId_WithDifferentPojoTypes() {
        // Arrange
        String stringPojo = "test-string";
        Integer intPojo = 123;
        String expectedId = "id-for-pojo";

        when(mockGenerator.generateId(any())).thenReturn(expectedId);

        // Act & Assert for String
        assertEquals(expectedId, writableObjectId.generateId(stringPojo));

        // Act & Assert for Integer
        assertEquals(expectedId, writableObjectId.generateId(intPojo));
    }
}
